package com.fasterxml.jackson.databind.deser;

import com.fasterxml.jackson.annotation.*;
import com.fasterxml.jackson.annotation.JsonProperty;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.annotation.JsonPOJOBuilder;
import com.fasterxml.jackson.databind.cfg.ConfigOverride;
import com.fasterxml.jackson.databind.cfg.DeserializerFactoryConfig;
import com.fasterxml.jackson.databind.deser.BeanDescription;
import com.fasterxml.jackson.databind.deser.BeanDeserializerFactory;
import com.fasterxml.jackson.databind.deser.BeanPropertyDefinition;
import com.fasterxml.jackson.databind.deser.SettableBeanProperty;
import com.fasterxml.jackson.databind.deser.impl.*;
import com.fasterxml.jackson.databind.deser.impl.FieldProperty;
import com.fasterxml.jackson.databind.deser.impl.MethodProperty;
import com.fasterxml.jackson.databind.deser.std.ThrowableDeserializer;
import com.fasterxml.jackson.databind.introspect.*;
import com.fasterxml.jackson.databind.jsontype.TypeDeserializer;
import com.fasterxml.jackson.databind.type.JavaType;
import com.fasterxml.jackson.databind.type.TypeFactory;
import com.fasterxml.jackson.databind.util.ClassUtil;
import com.fasterxml.jackson.databind.util.SimpleBeanPropertyDefinition;
import java.io.*;
import java.io.IOException;
import java.lang.annotation.Annotation;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.*;
import static org.mockito.Mockito.*;

public class BeanDeserializerFactory_constructSettableProperty_TriageGen2Test {

    private BeanDeserializerFactory factory;
    private DeserializationContext ctxt;
    private BeanDescription beanDesc;
    private BeanPropertyDefinition propDef;
    private JavaType propType;
    private TypeFactory typeFactory;

    // Test target class to simulate different mutator types
    static class TestBean {
        public String field;
        public void setField(String field) {}
    }

    @Before
    public void setUp() {
        factory = new BeanDeserializerFactory(null);
        ctxt = mock(DeserializationContext.class);
        beanDesc = mock(BeanDescription.class);
        propDef = mock(BeanPropertyDefinition.class);
        typeFactory = TypeFactory.defaultInstance();
        propType = typeFactory.constructType(String.class);

        when(beanDesc.getClassAnnotations()).thenReturn(null);
    }

    /**
     * Helper to spy the factory since the method is protected.
     * We need to mock resolveMemberAndTypeAnnotations and findDeserializerFromAnnotation 
     * which are internal/helper methods of the class.
     */
    private BeanDeserializerFactory createSpyFactory() {
        return spy(factory);
    }

    @Test
    public void testConstructSettableProperty_MethodProperty() throws Exception {
        BeanDeserializerFactory spyFactory = createSpyFactory();

        AnnotatedMethod mutator = mock(AnnotatedMethod.class);
        when(propDef.getNonConstructorMutator()).thenReturn(mutator);
        when(mutator.getAnnotation(JsonProperty.class)).thenReturn(null);

        // Mock internal calls via spy
        doReturn(propType).when(spyFactory).resolveMemberAndTypeAnnotations(any(), any(), any());
        doReturn(null).when(spyFactory).findDeserializerFromAnnotation(any(), any());

        // Mock type handler
        JavaType mockedType = mock(JavaType.class);
        when(propType.getTypeHandler()).thenReturn(null); // Simulating typeDeser
        when(propType.getValueHandler()).thenReturn(null);
        doReturn(mockedType).when(spyFactory).resolveMemberAndTypeAnnotations(any(), any(), any());

        SettableBeanProperty result = spyFactory.constructSettableProperty(ctxt, beanDesc, propDef, propType);

        assertNotNull(result);
        assertTrue(result instanceof MethodProperty);
    }

    @Test
    public void testConstructSettableProperty_FieldProperty() throws Exception {
        BeanDeserializerFactory spyFactory = createSpyFactory();

        AnnotatedField mutator = mock(AnnotatedField.class);
        when(propDef.getNonConstructorMutator()).thenReturn(mutator);

        doReturn(propType).when(spyFactory).resolveMemberAndTypeAnnotations(any(), any(), any());
        doReturn(null).when(spyFactory).findDeserializerFromAnnotation(any(), any());

        SettableBeanProperty result = spyFactory.constructSettableProperty(ctxt, beanDesc, propDef, propType);

        assertNotNull(result);
        assertTrue(result instanceof FieldProperty);
    }

    @Test(expected = JsonMappingException.class)
    public void testConstructSettableProperty_NoMutatorThrowsException() throws Exception {
        BeanDeserializerFactory spyFactory = createSpyFactory();
        when(propDef.getNonConstructorMutator()).thenReturn(null);

        spyFactory.constructSettableProperty(ctxt, beanDesc, propDef, propType);

        verify(ctxt).reportBadPropertyDefinition(eq(beanDesc), eq(propDef), contains("No non-constructor mutator available"));
    }

    @Test
    public void testConstructSettableProperty_WithDeserializerAndContextualization() throws Exception {
        BeanDeserializerFactory spyFactory = createSpyFactory();

        AnnotatedMethod mutator = mock(AnnotatedMethod.class);
        when(propDef.getNonConstructorMutator()).thenReturn(mutator);
        doReturn(propType).when(spyFactory).resolveMemberAndTypeAnnotations(any(), any(), any());

        // Mock finding a deserializer from annotation
        JsonDeserializer<?> mockDeser = mock(JsonDeserializer.class);
        doReturn(mockDeser).when(spyFactory).findDeserializerFromAnnotation(any(), any());

        // Mock contextualization
        JsonDeserializer<?> contextualizedDeser = mock(JsonDeserializer.class);
        when(ctxt.handlePrimaryContextualization(eq(mockDeser), any(), eq(propType))).thenReturn(contextualizedDeser);

        SettableBeanProperty result = spyFactory.constructSettableProperty(ctxt, beanDesc, propDef, propType);

        assertNotNull(result);
        // Verify result has the contextualized deserializer
        // Note: SettableBeanProperty.getValueDeserializer() is used to check
        assertEquals(contextualizedDeser, result.getValueDeserializer());
    }

    @Test
    public void testConstructSettableProperty_WithReferenceAndObjectId() throws Exception {
        BeanDeserializerFactory spyFactory = createSpyFactory();

        AnnotatedField mutator = mock(AnnotatedField.class);
        when(propDef.getNonConstructorMutator()).thenReturn(mutator);
        doReturn(propType).when(spyFactory).resolveMemberAndTypeAnnotations(any(), any(), any());
        doReturn(null).when(spyFactory).findDeserializerFromAnnotation(any(), any());

        // Mock Reference Property
        AnnotationIntrospector.ReferenceProperty ref = mock(AnnotationIntrospector.ReferenceProperty.class);
        when(ref.isManagedReference()).thenReturn(true);
        when(ref.getName()).thenReturn("myRef");
        when(propDef.findReferenceType()).thenReturn(ref);

        // Mock ObjectIdInfo
        ObjectIdInfo objectIdInfo = mock(ObjectIdInfo.class);
        when(propDef.findObjectIdInfo()).thenReturn(objectIdInfo);

        SettableBeanProperty result = spyFactory.constructSettableProperty(ctxt, beanDesc, propDef, propType);

        assertNotNull(result);
        assertEquals("myRef", result.getManagedReferenceName());
        assertEquals(objectIdInfo, result.getObjectIdInfo());
    }

    @Test
    public void testConstructSettableProperty_FallbackToValueHandler() throws Exception {
        BeanDeserializerFactory spyFactory = createSpyFactory();

        AnnotatedField mutator = mock(AnnotatedField.class);
        when(propDef.getNonConstructorMutator()).thenReturn(mutator);
        doReturn(propType).when(spyFactory).resolveMemberAndTypeAnnotations(any(), any(), any());

        // No annotation deserializer
        doReturn(null).when(spyFactory).findDeserializerFromAnnotation(any(), any());

        // But type has a value handler
        JsonDeserializer<?> valueHandler = mock(JsonDeserializer.class);
        JavaType mockedType = mock(JavaType.class);
        when(mockedType.getValueHandler()).thenReturn(valueHandler);
        doReturn(mockedType).when(spyFactory).resolveMemberAndTypeAnnotations(any(), any(), any());

        SettableBeanProperty result = spyFactory.constructSettableProperty(ctxt, beanDesc, propDef, propType);

        assertNotNull(result);
        assertEquals(valueHandler, result.getValueDeserializer());
    }
}

// Interfaces needed for mocking due to visibility/internal structure
interface AnnotatedMethod extends AnnotatedMember { }
interface AnnotatedField extends AnnotatedMember { }
interface AnnotatedMember { }
interface ObjectIdInfo extends Annotation { }
